// 通过 CDP 驱动真实 Chrome，验证分派等待期间编辑输入框的行为。
const base = "http://127.0.0.1:" + process.env.APP_PORT;

const list = await (await fetch("http://127.0.0.1:9222/json/list")).json();
const page = list.find(t => t.type === "page");
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise(res => ws.addEventListener("open", res, {once:true}));

let mid = 0;
const pending = new Map();
ws.addEventListener("message", ev => {
  const m = JSON.parse(ev.data);
  if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); }
});
function send(method, params={}){
  const id = ++mid;
  return new Promise(res => { pending.set(id, res); ws.send(JSON.stringify({id, method, params})); });
}
async function evaljs(expr){
  const r = await send("Runtime.evaluate", {expression: expr, returnByValue:true, awaitPromise:true});
  if (r.result && r.result.exceptionDetails) throw new Error(JSON.stringify(r.result.exceptionDetails));
  return r.result.result.value;
}
const sleep = ms => new Promise(r => setTimeout(r, ms));
async function waitFor(desc, fn, timeout=15000){
  const t0 = Date.now();
  for (;;){
    const v = await fn();
    if (v) return v;
    if (Date.now()-t0 > timeout) throw new Error("timeout waiting: " + desc);
    await sleep(100);
  }
}
function setInput(value){
  // 用 JS 设值不会自动触发事件，需手动派发 input，与真实键入的监听路径一致。
  return evaljs(`(function(){
    var el = document.getElementById("f-assignee");
    el.value = ${JSON.stringify(value)};
    el.dispatchEvent(new InputEvent("input", {bubbles:true}));
    return el.value;
  })()`);
}

await send("Runtime.enable");
await send("Page.enable");

// 打开应用（数据目录中已有 TKT-000001，当前负责人 李四）
await send("Page.navigate", {url: base + "/"});
await waitFor("list buttons", () => evaljs(`!!document.querySelector('button[data-i]')`));
await evaljs(`document.querySelector('button[data-i]').click()`);
await waitFor("detail open", () => evaljs(`document.getElementById("detail").classList.contains("open")`));

const state = async () => evaljs(`(function(){
  var n = document.getElementById("assign-notice");
  var b = document.getElementById("assign-btn");
  var assigneeDD = "";
  Array.prototype.forEach.call(document.querySelectorAll("dl dt"), function(dt){
    if (dt.textContent === "负责人") assigneeDD = dt.nextElementSibling.textContent;
  });
  return JSON.stringify({
    input: document.getElementById("f-assignee").value,
    notice: n ? n.textContent : "",
    btnDisabled: b.disabled,
    btnText: b.textContent,
    assignee: assigneeDD,
    records: Array.prototype.map.call(document.querySelectorAll(".assign-list li"), li => li.textContent),
    listAssignees: Array.prototype.map.call(document.querySelectorAll("tbody tr"), tr => tr.children[5].textContent)
  });
})()`).then(JSON.parse);

