await waitFor("D done", async () => !(await state()).btnDisabled);
s = await state();
console.log("场景D返回:", JSON.stringify(s, null, 2));
if (s.input !== "钱七") throw new Error("D: 网络失败后输入未保留，实际 " + JSON.stringify(s.input));
if (!/此前分派给“李四”的请求失败：无法连接服务/.test(s.notice)) throw new Error("D: 失败提示未对应此前请求（李四）：" + s.notice);
