if (s.input !== "") throw new Error("B: 无编辑时成功后应清空输入，实际 " + JSON.stringify(s.input));
if (!/^分派成功，负责人：李四/.test(s.notice)) throw new Error("B: 提示错误：" + s.notice);
if (s.assignee !== "李四") throw new Error("B: 负责人应为李四");
const recordsBefore = s.records.length;

// ---- 场景 C：提交与当前相同的负责人李四（未变化），等待期间填入带首尾空白的“  赵六 ” ----
await send("Network.emulateNetworkConditions", {offline:false, latency:1500, downloadThroughput:-1, uploadThroughput:-1});
await setInput("李四");
await evaljs(`document.getElementById("assign-btn").click()`);
await waitFor("sending C", async () => (await state()).btnText === "正在分派…");
await setInput("  赵六 ");
await waitFor("C done", async () => !(await state()).btnDisabled);
s = await state();
console.log("场景C返回:", JSON.stringify(s, null, 2));
if (s.input !== "  赵六 ") throw new Error("C: 首尾空白未原样保留，实际 " + JSON.stringify(s.input));
if (!/负责人未变化，仍为：李四/.test(s.notice)) throw new Error("C: 未变化提示错误：" + s.notice);
if (!/尚未提交/.test(s.notice)) throw new Error("C: 缺少尚未提交提示：" + s.notice);
if (s.records.length !== recordsBefore) throw new Error("C: 负责人未变化却新增了分派记录");
if (s.assignee !== "李四") throw new Error("C: 负责人不应变化");

// ---- 场景 D：网络失败时当前输入原样保留，提示对应此前请求 ----
// 离线时 fetch 会立即失败；先用高延迟让请求挂起，提交后再离线并把输入改成周八。
