await send("Network.emulateNetworkConditions", {offline:false, latency:1500, downloadThroughput:-1, uploadThroughput:-1});
await evaljs(`document.getElementById("assign-btn").click()`);
await waitFor("sending D", async () => (await state()).btnText === "正在分派…");
await send("Network.emulateNetworkConditions", {offline:true, latency:0, downloadThroughput:-1, uploadThroughput:-1});
// 等待期间再改成周八：失败提示必须对应已发出的钱七，输入保留周八
await setInput("周八");
await waitFor("D done", async () => { const x = await state(); return !x.btnDisabled && /无法连接服务/.test(x.notice); });
s = await state();
console.log("场景D返回:", JSON.stringify(s, null, 2));
if (s.input !== "周八") throw new Error("D: 网络失败后输入未保留周八，实际 " + JSON.stringify(s.input));
if (!/此前分派给“钱七”的请求失败：无法连接服务/.test(s.notice)) throw new Error("D: 失败提示未对应此前请求（钱七）：" + s.notice);
if (/周八/.test(s.notice)) throw new Error("D: 不得把后来输入的周八描述为已分派");

console.log("\n全部断言通过 ✔");
ws.close();
process.exit(0);

