// ---- 场景 C：提交与当前相同的负责人李四（未变化），等待期间填入带首尾空白的“  赵六 ” ----
await send("Network.emulateNetworkConditions", {offline:false, latency:1500, downloadThroughput:-1, uploadThroughput:-1});
await setInput("李四");
await evaljs(`document.getElementById("assign-btn").click()`);
await waitFor("sending C", async () => (await state()).btnText === "正在分派…");
await setInput("  赵六 ");
await waitFor("C done", async () => !(await state()).btnDisabled);
s = await state();
console.log("场景C返回:", JSON.stringify(s, null, 2));
if (s.input !== "  赵六 ") throw new Error("C: 首尾空白未原样保留，实际 " + JSON.stringify(s.input));
if (!/负责人未变化，仍为：李四/.test(s.notice)) throw new Error("C: 未变化提示错误：" + s.notice);
if (!/尚未提交/.test(s.notice)) throw new Error("C: 缺少尚未提交提示：" + s.notice);
if (s.records.length !== recordsBefore) throw new Error("C: 负责人未变化却新增了分派记录");
if (s.assignee !== "李四") throw new Error("C: 负责人不应变化");

// ---- 场景 D：请求失败时当前输入原样保留，提示对应此前请求 ----
// 用 Fetch 拦截把分派请求挂起，等待期间改成周八，再令请求失败：
// 失败提示必须对应已发出的钱七，输入保留周八。
let pausedResolver = null;
ws.addEventListener("message", ev => {
  const m = JSON.parse(ev.data);
  if (m.method === "Fetch.requestPaused" && pausedResolver) { pausedResolver(m.params); pausedResolver = null; }
});
await send("Fetch.enable", {patterns:[{urlPattern:"*assignment*", requestStage:"Request"}]});
const paused = new Promise(res => { pausedResolver = res; });
await setInput("钱七");
await send("Network.emulateNetworkConditions", {offline:false, latency:0, downloadThroughput:-1, uploadThroughput:-1});
await evaljs(`document.getElementById("assign-btn").click()`);
await waitFor("sending D", async () => (await state()).btnText === "正在分派…");
await setInput("周八");
const pausedParams = await paused;
await send("Fetch.failRequest", {requestId: pausedParams.requestId, errorReason: "Failed"});
await waitFor("D done", async () => { const x = await state(); return !x.btnDisabled && /无法连接服务/.test(x.notice); });
s = await state();
console.log("场景D返回:", JSON.stringify(s, null, 2));
if (s.input !== "周八") throw new Error("D: 网络失败后输入未保留周八，实际 " + JSON.stringify(s.input));
if (!/此前分派给“钱七”的请求失败：无法连接服务/.test(s.notice)) throw new Error("D: 失败提示未对应此前请求（钱七）：" + s.notice);
if (/周八/.test(s.notice)) throw new Error("D: 不得把后来输入的周八描述为已分派");

console.log("\n全部断言通过 ✔");
ws.close();
process.exit(0);

