// 用 Fetch 拦截把分派请求挂起，等待期间改成周八，再令请求失败：
// 失败提示必须对应已发出的钱七，输入保留周八。
const pausedQueue = [];
let pausedWait = null;
ws.addEventListener("message", ev => {
  const m = JSON.parse(ev.data);
  if (m.method === "Fetch.requestPaused") {
    if (pausedWait) { const r = pausedWait; pausedWait = null; r(m.params); }
    else pausedQueue.push(m.params);
  }
});
